const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [settings, setSettings] = useState<WorkshopSettings>(getSettings());

  useEffect(() => {
    setTimeout(() => setLoading(false), 2000);
  }, []);

  const handleSave = (service: ServiceRecord) => {
    saveService(service);
    setView('DASHBOARD');
    setSelectedId(null);
  };

  const handleSaveSettings = (newSettings: WorkshopSettings) => {
    saveSettings(newSettings);
    setSettings(newSettings);
    setView('DASHBOARD');
  };

  if (loading) return <SplashScreen onFinish={() => setLoading(false)} />;

  return (
    <div className="max-w-md mx-auto bg-white dark:bg-slate-950 min-h-screen shadow-2xl overflow-hidden relative">
      {view === 'DASHBOARD' && (
        <Dashboard 
          settings={settings}
          onSettings={() => setView('SETTINGS')}
          onNew={() => { setSelectedId(null); setView('CREATE_EDIT'); }}
          onSelect={(id) => { setSelectedId(id); setView('DETAILS'); }}
        />
      )}

      {view === 'SETTINGS' && (
        <SettingsPanel 
          settings={settings}
          onSave={handleSaveSettings}
          onBack={() => setView('DASHBOARD')}
        />
      )}

      {view === 'CREATE_EDIT' && (
        <ServiceForm 
          initialData={selectedId ? getServices().find(s => s.id === selectedId) : undefined}
          onSave={handleSave}
          onCancel={() => setView('DASHBOARD')}
        />
      )}

      {view === 'DETAILS' && selectedId && (
        <ServiceDetails 
          service={getServices().find(s => s.id === selectedId)!} 
          settings={settings}
          onBack={() => setView('DASHBOARD')}
          onEdit={() => setView('CREATE_EDIT')}
        />
      )}
    </div>
  );
};

export default App;

