const ServiceForm: React.FC<{
  initialData?: ServiceRecord;
  onSave: (service: ServiceRecord) => void;
  onCancel: () => void;
}> = ({ initialData, onSave, onCancel }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState<ServiceRecord>(initialData || {
    id: generateId(),
    carPlate: '', carModel: '', carYear: '', carColor: '', carMileage: '',
    ownerName: '', ownerPhone: '',
    entryDate: new Date().toISOString().split('T')[0],
    description: '', diagnosis: '',
    laborCost: 0, laborDescription: '',
    parts: [],
    warrantyInfo: '3 meses garantia legal',
    status: ServiceStatus.ANALYSIS,
    createdAt: Date.now(), updatedAt: Date.now()
  });
  const [tempPart, setTempPart] = useState<Part>({ id: '', name: '', quantity: 1, unitPrice: 0 });

  const handleChange = (field: keyof ServiceRecord, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const addPart = () => {
    if (!tempPart.name || tempPart.unitPrice <= 0) return;
    const newPart = { ...tempPart, id: generateId() };
    setFormData(prev => ({ ...prev, parts: [...prev.parts, newPart] }));
    setTempPart({ id: '', name: '', quantity: 1, unitPrice: 0 });
  };

  const removePart = (id: string) => {
    setFormData(prev => ({ ...prev, parts: prev.parts.filter(p => p.id !== id) }));
  };

  const renderStep1 = () => (
    <div className="space-y-4 animate-enter">
      <h3 className="text-lg font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2"><Car className="text-indigo-500" size={20}/> Veículo</h3>
      <div className="grid grid-cols-2 gap-4">
        <Input label="Placa" placeholder="ABC-1234" value={formData.carPlate} onChange={e => handleChange('carPlate', e.target.value)} className="uppercase" />
        <Input label="Modelo" placeholder="Ex: Fiat Uno" value={formData.carModel} onChange={e => handleChange('carModel', e.target.value)} />
      </div>
      <div className="grid grid-cols-3 gap-3">
        <Input label="Ano" type="number" value={formData.carYear} onChange={e => handleChange('carYear', e.target.value)} />
        <Input label="Cor" value={formData.carColor} onChange={e => handleChange('carColor', e.target.value)} />
        <Input label="KM" type="number" value={formData.carMileage} onChange={e => handleChange('carMileage', e.target.value)} />
      </div>
      <h3 className="text-lg font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2 mt-6"><User className="text-indigo-500" size={20}/> Proprietário</h3>
      <Input label="Nome Completo" value={formData.ownerName} onChange={e => handleChange('ownerName', e.target.value)} />
      <Input label="Telefone / WhatsApp" type="tel" value={formData.ownerPhone} onChange={e => handleChange('ownerPhone', e.target.value)} />
    </div>
  );

  const renderStep2 = () => (
    <div className="space-y-4 animate-enter">
      <h3 className="text-lg font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2"><AlertCircle className="text-indigo-500" size={20}/> Problema</h3>
      <TextArea label="Relato do Cliente" value={formData.description} onChange={e => handleChange('description', e.target.value)} />
      <TextArea label="Diagnóstico Técnico" value={formData.diagnosis} onChange={e => handleChange('diagnosis', e.target.value)} />
      <div className="p-4 bg-indigo-50 dark:bg-indigo-900/20 rounded-xl mt-4">
        <label className="text-sm font-bold text-indigo-900 dark:text-indigo-300 mb-2 block">Status Atual</label>
        <div className="flex flex-wrap gap-2">
          {Object.values(ServiceStatus).map(status => (
             <button
               key={status}
               onClick={() => handleChange('status', status)}
               className={`text-xs px-3 py-2 rounded-lg border transition-all ${formData.status === status ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white dark:bg-slate-800 text-slate-600 border-slate-200'}`}
             >
               {status}
             </button>
          ))}
        </div>
      </div>
    </div>
  );

  const renderStep3 = () => (
    <div className="space-y-5 animate-enter">
      <h3 className="text-lg font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2"><DollarSign className="text-indigo-500" size={20}/> Orçamento</h3>
      <div className="p-4 bg-slate-50 dark:bg-slate-900 rounded-2xl border border-slate-100">
        <div className="grid grid-cols-6 gap-2 mb-2">
          <div className="col-span-6"><Input placeholder="Peça" value={tempPart.name} onChange={e => setTempPart({...tempPart, name: e.target.value})} className="text-sm" /></div>
          <div className="col-span-2"><Input type="number" placeholder="Qtd" value={tempPart.quantity} onChange={e => setTempPart({...tempPart, quantity: Number(e.target.value)})} className="text-sm" /></div>
          <div className="col-span-2"><Input type="number" placeholder="R$" value={tempPart.unitPrice} onChange={e => setTempPart({...tempPart, unitPrice: Number(e.target.value)})} className="text-sm" /></div>
          <div className="col-span-2"><Button onClick={addPart} size="sm" fullWidth className="h-full">+</Button></div>
        </div>
      </div>
      <div className="space-y-2">
        {formData.parts.map((part, idx) => (
          <div key={idx} className="flex justify-between items-center p-3 bg-white dark:bg-slate-800 border rounded-xl">
