          </div>
        ))}
      </div>
      <Input label="Mão de Obra (R$)" type="number" value={formData.laborCost} onChange={e => handleChange('laborCost', Number(e.target.value))} />
      <div className="bg-slate-900 text-white p-4 rounded-xl flex justify-between items-center">
        <span className="font-medium opacity-60">Total</span>
        <span className="text-2xl font-bold">R$ {calculateTotal(formData).toFixed(2)}</span>
      </div>
    </div>
  );

  const renderStep4 = () => (
    <div className="space-y-5 animate-enter">
       <h3 className="text-lg font-bold text-slate-800 dark:text-slate-200 flex items-center gap-2"><PenTool className="text-indigo-500" size={20}/> Autorização</h3>
       <Input label="Termos de Garantia" value={formData.warrantyInfo} onChange={e => handleChange('warrantyInfo', e.target.value)} />
       <div>
         <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">Assinatura Digital do Cliente <span className="text-red-500">*</span></label>
         <SignaturePad onSave={(signature) => handleChange('clientSignature', signature)} existingSignature={formData.clientSignature} />
         {!formData.clientSignature && <p className="text-xs text-red-400 mt-2">A assinatura é obrigatória para prosseguir.</p>}
       </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 pb-24">
      <Header title={initialData ? "Editar" : "Novo"} onBack={onCancel} />
      <div className="p-5">{step === 1 && renderStep1()}{step === 2 && renderStep2()}{step === 3 && renderStep3()}{step === 4 && renderStep4()}</div>
      <div className="fixed bottom-0 left-0 right-0 p-4 bg-white/90 dark:bg-slate-900/90 backdrop-blur-lg border-t flex gap-3 z-20">
        {step > 1 && <Button variant="outline" onClick={() => setStep(s => s - 1)} className="flex-1">Voltar</Button>}
        {step < 4 ? <Button onClick={() => setStep(s => s + 1)} fullWidth className="flex-[2]">Próximo</Button> : <Button onClick={() => onSave(formData)} variant="success" fullWidth className="flex-[2]" disabled={!formData.clientSignature}>Finalizar</Button>}
      </div>
    </div>
  );
};

