// --- Theme Toggle ---
const ThemeToggle: React.FC = () => {
  const [isDark, setIsDark] = useState(document.documentElement.classList.contains('dark'));
  const toggleTheme = () => {
    document.documentElement.classList.toggle('dark');
    setIsDark(!isDark);
    localStorage.theme = !isDark ? 'dark' : 'light';
  };
  return (
    <button onClick={toggleTheme} className="p-2.5 rounded-xl bg-slate-100 dark:bg-slate-800 text-slate-600">
      {isDark ? <Sun size={20} /> : <Moon size={20} />}
    </button>
  );
};

// --- App Component ---

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>('DASHBOARD');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [settings, setSettings] = useState<WorkshopSettings | null>(null);
  const [services, setServices] = useState<ServiceRecord[]>([]);

  useEffect(() => {
    const init = async () => {
      const s = await db.getSettings();
      const sv = await db.getServices();
      setSettings(s);
      setServices(sv);
    };
    init();
  }, [view]);

  const handleSave = async (service: ServiceRecord) => {
    await db.saveService(service);
    setView('DASHBOARD');
  };

  const handleSaveSettings = async (newSettings: WorkshopSettings) => {
    await db.saveSettings(newSettings);
    setSettings(newSettings);
    setView('DASHBOARD');
  };

  if (!settings) return null;

  return (
    <div className="max-w-md mx-auto bg-white dark:bg-slate-950 min-h-screen shadow-2xl relative">
      {view === 'DASHBOARD' && (
        <Dashboard 
          settings={settings}
          onSettings={() => setView('SETTINGS')}
          onNew={() => { setSelectedId(null); setView('CREATE_EDIT'); }}
          onSelect={(id) => { setSelectedId(id); setView('DETAILS'); }}
        />
      )}
      {view === 'SETTINGS' && <SettingsPanel settings={settings} onSave={handleSaveSettings} onBack={() => setView('DASHBOARD')} />}
      {view === 'CREATE_EDIT' && (
        <ServiceForm 
          initialData={selectedId ? services.find(s => s.id === selectedId) : undefined}
          onSave={handleSave}
          onCancel={() => setView('DASHBOARD')}
        />
      )}
      {view === 'DETAILS' && selectedId && services.find(s => s.id === selectedId) && (
        <ServiceDetails 
          service={services.find(s => s.id === selectedId)!} 
          settings={settings}
          onBack={() => setView('DASHBOARD')}
          onEdit={() => setView('CREATE_EDIT')}
        />
      )}
    </div>
  );
};

export default App;

export enum ServiceStatus {
  ANALYSIS = 'Em Análise',
  PENDING_APPROVAL = 'Aguardando Aprovação',
  IN_PROGRESS = 'Em Execução',
  READY = 'Pronto',
  COMPLETED = 'Concluído'
}

export interface Part {
  id: string;
  name: string;
  quantity: number;
  unitPrice: number;
}

export interface WorkshopSettings {
  name: string;
  phone: string;
  address: string;
}

export interface ServiceRecord {
  id: string;
  // Car Info
  carPlate: string;
  carModel: string;
  carYear: string;
  carColor: string;
  carMileage: string;
  // Owner Info
  ownerName: string;
  ownerPhone: string;
  // Service Info
  entryDate: string;
  scheduledDate?: string; // New field
  scheduledTime?: string; // New field
  description: string; // Problem reported
  diagnosis: string;
  laborCost: number;
  laborDescription: string;
  parts: Part[];
  warrantyInfo: string;
  // Meta
  status: ServiceStatus;
  clientSignature?: string; // Base64 string
  createdAt: number;
  updatedAt: number;
}

